package com.deadlands.world.biome;

import com.deadlands.Deadlands;
import java.util.List;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.tags.TagKey;
import net.minecraft.world.level.biome.Biome;

/**
 * The ten DEADLANDS biomes. Their definitions are data (data/deadlands/worldgen/biome, generated by
 * tools/assetgen/gen_world.py); this class only names them for code that needs to refer to them.
 */
public final class DLBiomes {
	public static final ResourceKey<Biome> DEAD_FOREST = key("dead_forest");
	public static final ResourceKey<Biome> OVERGROWN_SUBURBS = key("overgrown_suburbs");
	public static final ResourceKey<Biome> ABANDONED_FARMLAND = key("abandoned_farmland");
	public static final ResourceKey<Biome> DRY_WASTELAND = key("dry_wasteland");
	public static final ResourceKey<Biome> FLOODED_MARSH = key("flooded_marsh");
	public static final ResourceKey<Biome> DEAD_PINE_VALLEY = key("dead_pine_valley");
	public static final ResourceKey<Biome> FROZEN_OUTSKIRTS = key("frozen_outskirts");
	public static final ResourceKey<Biome> INDUSTRIAL_WASTELAND = key("industrial_wasteland");
	public static final ResourceKey<Biome> BURNED_FOREST = key("burned_forest");
	public static final ResourceKey<Biome> RURAL_COUNTRYSIDE = key("rural_countryside");

	public static final List<ResourceKey<Biome>> ALL = List.of(
		DEAD_FOREST, OVERGROWN_SUBURBS, ABANDONED_FARMLAND, DRY_WASTELAND, FLOODED_MARSH,
		DEAD_PINE_VALLEY, FROZEN_OUTSKIRTS, INDUSTRIAL_WASTELAND, BURNED_FOREST, RURAL_COUNTRYSIDE
	);

	/** Every DEADLANDS biome. */
	public static final TagKey<Biome> IS_DEADLANDS = TagKey.create(Registries.BIOME, Deadlands.id("is_deadlands"));
	/** Biomes where towns can be founded (and where the road network looks for them). */
	public static final TagKey<Biome> HAS_TOWN = TagKey.create(Registries.BIOME, Deadlands.id("has_structure/town"));

	private DLBiomes() {
	}

	private static ResourceKey<Biome> key(String name) {
		return ResourceKey.create(Registries.BIOME, Deadlands.id(name));
	}
}
